#
# NEW DICTIONARY: built over 5 pilot rounds (64t_king_dictionary_pilot.R)
# against King (1981)'s own language on what career politicians DO
# (ambition, self-assertion, disputatiousness) rather than what they call
# their own job title. See 64u_career_orientation_split_1979_2019.R's
# header for the full pilot history — the short version: King's own
# academic vocabulary essentially never occurs in real speech; natural-
# language paraphrases of the same constructs do occur, but ~80x sparser
# than office-reference language; two apparently-productive phrases turned
# out to be contaminated (generic policy/scrutiny rhetoric) and were
# dropped; naked personal-ambition phrasing never occurs at all (a
# substantive finding about institutional self-effacement, not a dictionary
# failure).
#
# WHY A 5-YEAR ROLLING WINDOW: the annual series (64u/64v/64w) is real but
# unusable at annual resolution — individual years are driven by single-
# digit raw hit counts (e.g. 2025 frontbench = 2 hits/764 speeches),
# producing pure noise (annual swings of 0.26%-2.52% with no visible
# trend). 64x_career_orientation_rolling.R sums raw hits across a centred
# 5-year window BEFORE taking the ratio (not a rolling mean of the already-
# noisy annual ratios) - the only version of smoothing that actually pools
# the sparse signal. This reveals real structure: two frontbench peaks
# (~1993, ~2017) either side of a trough (~1998), and a backbench rise into
# 2013-2016.
#
# ⚠⚠ NO FORMAL BREAK TEST, unlike every other Ch3 figure — deliberate, not
# an oversight. The Chow/permutation method used everywhere else in this
# chapter assumes independent observations; a 5-year ROLLING (overlapping)
# window shares 4 of every 5 years with its neighbours, inducing exactly
# the kind of serial correlation that would inflate significance if fed
# into that test uncorrected. Reported instead: non-overlapping period
# means (1979-88/89-97/98-2009/2010-19/2020-25, the same bins used
# everywhere else in Ch3), which ARE independent of each other.
#
# House style: same theme file as fig_3_1-3_2/3_4-3_6, greyscale.
#
# OUTPUT: figures/fig_3_2_hansard_self_regarding.png
#         FIG32_FOOTNOTE_NOTES.md

suppressMessages({library(dplyr); library(readr); library(ggplot2); library(tidyr)})

.ROOT <- local({
  a <- commandArgs(trailingOnly = FALSE)
  m <- grep("^--file=", a, value = TRUE)
  if (length(m) == 1) normalizePath(file.path(dirname(sub("^--file=", "", m)), ".."))
  else getwd()
})
PROJECT   <- .ROOT
WKBD_ROOT <- normalizePath(file.path(PROJECT, "..", ".."))
source(file.path(WKBD_ROOT, "data_workspace_2026-07", "figure_house_theme.R"))

d <- read_csv(file.path(WKBD_ROOT, "online_appendix/ch3_career_orientation_rolling5yr_1979_2025.csv"),
              show_col_types = FALSE) |>
  arrange(year)

# ============================================================
# FIGURE — house style
# ============================================================
CANVAS_W <- house_width_in()

long_d <- d |>
  select(year, backbench_ratio_5yr, frontbench_ratio_5yr) |>
  pivot_longer(-year, names_to = "group", values_to = "ratio") |>
  mutate(group = recode(group, backbench_ratio_5yr = "Backbench", frontbench_ratio_5yr = "Frontbench"))

p <- ggplot(long_d, aes(year, ratio, linetype = group)) +
  geom_line(colour = "#000000", linewidth = 0.8) +
  geom_point(colour = "#000000", size = 0.9) +
  annotate("text", x = 1993, y = 0.0168, label = "Frontbench", colour = "grey35",
           fontface = "italic", size = mm_for(PRINTED$caption, CANVAS_W)) +
  annotate("text", x = 1993, y = 0.0055, label = "Backbench", colour = "grey35",
           fontface = "italic", size = mm_for(PRINTED$caption, CANVAS_W)) +
  scale_linetype_manual(values = c("Backbench" = "solid", "Frontbench" = "dashed")) +
  scale_x_continuous(breaks = seq(1980, 2020, 5), limits = c(1979, 2025)) +
  scale_y_continuous(labels = scales::percent_format(accuracy = 0.1)) +
  guides(linetype = "none") +
  labs(
    title = paste0(
      "Figure 3.2: Career-orientation speech, backbench vs\n",
      "frontbench, House of Commons, 1979-2025"
    ),
    x = NULL, y = "Career-orientation ratio (5yr rolling mean)"
  ) +
  house_print(CANVAS_W)

OUT <- file.path(PROJECT, "figures/fig_3_2_hansard_self_regarding.png")
ggsave(OUT, p, width = CANVAS_W, height = CANVAS_W * 0.58, dpi = HOUSE_DPI, bg = "white")
cat("Figure saved:", OUT, "\n")

# ============================================================
# FOOTNOTE NOTES — generated so numbers cannot drift from the figure
# ============================================================
period <- function(dd, y0, y1, col) dd |> filter(year >= y0, year <= y1) |> summarise(m = mean({{col}}, na.rm = TRUE)) |> pull(m)

p1_bb <- period(d, 1979, 1988, backbench_ratio_5yr); p1_fb <- period(d, 1979, 1988, frontbench_ratio_5yr)
p2_bb <- period(d, 1989, 1997, backbench_ratio_5yr); p2_fb <- period(d, 1989, 1997, frontbench_ratio_5yr)
p3_bb <- period(d, 1998, 2009, backbench_ratio_5yr); p3_fb <- period(d, 1998, 2009, frontbench_ratio_5yr)
p4_bb <- period(d, 2010, 2019, backbench_ratio_5yr); p4_fb <- period(d, 2010, 2019, frontbench_ratio_5yr)
p5_bb <- period(d, 2020, 2025, backbench_ratio_5yr); p5_fb <- period(d, 2020, 2025, frontbench_ratio_5yr)
min_bb_hits <- min(d$backbench_hits_5yr); min_fb_hits <- min(d$frontbench_hits_5yr)
peak_fb_year1 <- d$year[d$year <= 2000][which.max(d$frontbench_ratio_5yr[d$year <= 2000])]
peak_fb_year2 <- d$year[d$year > 2000][which.max(d$frontbench_ratio_5yr[d$year > 2000])]
trough_bb_year <- d$year[which.min(d$backbench_ratio_5yr)]

